const r2=n=>Math.round(n*100)/100;
const tidy=s=>s.replace(/-?\d+\.\d{3,}/g,m=>String(r2(+m)));

// ---- bottle ------------------------------------------------------------------------------
const TOP='M81.6 81.4Q81.6 77.9 85.2 77.4Q100 75.7 114.8 77.4Q118.4 77.9 118.4 81.4V107.5C118.4 110 119.6 111 121 112C127.5 116.5 131.6 123 132.7 132L132.84 136';
