// ---- shared label parts ------------------------------------------------------------------
const INK='#0c0c0c',YEL='#f6ee08',PAPER='#fbfaf8';
// The logotype. `letters`/`runner`/`sticker` default to the tracing from the Regular Strength
// Berry bottle. The 2025 labels print it on a white die-cut backing with a soft shadow; the
// earlier label prints the black letters with their yellow outline straight onto the gradient.
function logo({letters=P.logoLetters,runner=P.logoRunner,sticker=P.logoSticker,runnerOutline=false,transform=''}={}){
  return `<g${transform?` transform="${transform}"`:''}>${sticker?`<path d="${sticker}" fill="#000" fill-opacity=".22" transform="translate(.8 1)"/><path d="${sticker}" fill="${PAPER}"/>`:''}
<path d="${letters}" fill="${INK}" stroke="${YEL}" stroke-width=".9" paint-order="stroke"/>
<path d="${runner}" fill="${INK}"${runnerOutline?` stroke="${YEL}" stroke-width=".8" stroke-linejoin="round" paint-order="stroke"`:''}/></g>`;
}
// Claim words (yellow bold italic), each traced with its origin at the left end of its baseline.
const word=(d,x,y,{stroke='#0a3a80',sx=1,sy=sx,fill='#f8f005'}={})=>`<path d="${d}" fill="${fill}" fill-rule="evenodd"${stroke?` stroke="${stroke}" stroke-width="${r2(.95/sy)}" stroke-linejoin="round" paint-order="stroke"`:''} transform="translate(${x} ${y})${sx===1&&sy===1?'':` scale(${sx} ${sy})`}"/>`;
// The flavor name in the label's heavy slab face, traced from the Berry cap; (cx,cy) is its centre.
const berry=(cx,cy,s,rot,fill,stroke,sw)=>`<path d="${P.berryCap}" fill="${fill}" fill-rule="evenodd"${stroke?` stroke="${stroke}" stroke-width="${r2(sw/s)}" stroke-linejoin="round" paint-order="stroke"`:''} transform="translate(${cx} ${cy}) rotate(${rot}) scale(${s}) translate(-99.2 -92.8)"/>`;
// Thin extended capitals (the light face of STRENGTH and TASTY) as centre lines in a w x h box.
const GLYPH={
  S:(w,h,c)=>`M${w} ${c+.1*h}V${c}Q${w} 0 ${w-c} 0H${c}Q0 0 0 ${c}V${h/2-c}Q0 ${h/2} ${c} ${h/2}H${w-c}Q${w} ${h/2} ${w} ${h/2+c}V${h-c}Q${w} ${h} ${w-c} ${h}H${c}Q0 ${h} 0 ${h-c}V${h-c-.1*h}`,
  T:(w,h)=>`M0 0H${w}M${w/2} 0V${h}`,
  R:(w,h,c)=>`M0 ${h}V0H${w-c}Q${w} 0 ${w} ${c}V${h/2-c}Q${w} ${h/2} ${w-c} ${h/2}H0M${w-c} ${h/2}Q${w} ${h/2} ${w} ${h/2+c}V${h}`,
  E:(w,h)=>`M${w} 0H0V${h}H${w}M0 ${h/2}H${.92*w}`,
  N:(w,h)=>`M0 ${h}V0L${w} ${h}V0`,
  G:(w,h,c)=>`M${w} ${c+.1*h}V${c}Q${w} 0 ${w-c} 0H${c}Q0 0 0 ${c}V${h-c}Q0 ${h} ${c} ${h}H${w-c}Q${w} ${h} ${w} ${h-c}V${h/2}H${.5*w}`,
  H:(w,h)=>`M0 0V${h}M${w} 0V${h}M0 ${h/2}H${w}`,
  A:(w,h)=>`M0 ${h}L${w/2} 0L${w} ${h}M${.17*w} ${.68*h}H${.83*w}`,
  Y:(w,h)=>`M0 0L${w/2} ${.56*h}L${w} 0M${w/2} ${.56*h}V${h}`,
};
// letters: [[char, left, width], ...]; top and h are the centre-line cap box.
const mono=(letters,top,h,c,attrs)=>`<g fill="none" stroke-linejoin="round" ${attrs}>${letters.map(([ch,x,w])=>`<path d="${tidy(GLYPH[ch](w,h,c))}" transform="translate(${r2(x)} ${top})"/>`).join('')}</g>`;
const spread=(str,x0,x1,w)=>[...str].map((ch,i,a)=>[ch,x0+i*(x1-x0-w)/(a.length-1),w]);
// The line of small print along the bottom edge; it follows the sleeve's curve.
const micro=parts=>parts.map(([label,x,y,len,rot=0,size=2.5,weight='bold'])=>`<text x="${x}" y="${y}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${size}" font-weight="${weight}" fill="#fff" textLength="${len}" lengthAdjust="spacingAndGlyphs"${rot?` transform="rotate(${rot} ${x} ${y})"`:''}>${label}</text>`).join('');
const seed=(x,y,s=1,fill='#f4a9b1')=>`<path d="M0-1.75C.5-.65 .95.15 .95.8A.95.95 0 1 1-.95.8C-.95.15-.5-.65 0-1.75Z" transform="translate(${x} ${y}) scale(${s})" fill="${fill}"/>`;
const fade=(id,y1,y2,stops)=>`<linearGradient id="__ID__${id}" gradientUnits="userSpaceOnUse" x1="0" y1="${y1}" x2="0" y2="${y2}">${stops.map(([o,c])=>`<stop offset="${o}" stop-color="${c}"/>`).join('')}</linearGradient>`;

